<template><div class="card"><div class="toolbar"><h3>{{tr('检查并发布已保存内容','Check and publish saved content')}}</h3><div class="btn-group"><button class="btn btn-outline" :disabled="busy" @click="check">{{tr('运行内容检查','Run content checks')}}</button><button class="btn btn-primary" :disabled="busy||!report||report.errors>0||report.restartRequired" @click="publish">{{tr('构建 → 部署 → 验证线上','Build → Deploy → Verify online')}}</button></div></div><p class="text-sm text-muted">{{tr('先在编辑器保存。流程锁定内容版本；只有线上版本标记及 HTML 与构建一致，才记为验证通过。','Save in the editor first. The workflow pins content revisions and verifies the online marker and HTML against the build.')}}</p><label class="check-drafts text-sm"><input v-model="includeDrafts" type="checkbox" @change="report=null">{{tr('内容检查包含草稿','Include drafts in checks')}}</label><template v-if="report"><p v-if="report.restartRequired" class="task-error">{{tr('配置文件已变化，请先重启 Hexo 后再发布。','Configuration files changed. Restart Hexo before publishing.')}}</p><p>{{report.errors}} {{tr('个错误','errors')}} · {{report.warnings}} {{tr('个警告','warnings')}} · {{report.revision.slice(0,12)}}</p><p class="text-sm text-muted">{{report.scope}}</p><div class="check-issues"><div v-for="(issue,index) in report.issues" :key="index" :class="issue.severity==='error'?'task-error':''"><a v-if="issue.editorPath" :href="'#'+issue.editorPath">{{issue.source}}:{{issue.line}} · {{issue.field}}</a><strong v-else>{{issue.source}}:{{issue.line}} · {{issue.field}}</strong><p>{{issue.message}}</p></div></div></template></div></template>
<script setup>
import {ref} from 'vue';import {api} from '../api/client';import {useI18n} from '../i18n';
const {tr,errorMessage}=useI18n();const emit=defineEmits(['notify','started']);const busy=ref(false),report=ref(null),includeDrafts=ref(false);
async function check(){busy.value=true;try{report.value=await api.get('/checks?include_drafts='+includeDrafts.value);}catch(error){emit('notify',errorMessage(error),'error');}finally{busy.value=false;}}
async function publish(){busy.value=true;try{await api.post('/publishing/run',{revision:report.value.revision});report.value=null;emit('started');emit('notify',tr('发布流程已进入队列','Publish workflow queued'),'success');}catch(error){emit('notify',errorMessage(error),'error');}finally{busy.value=false;}}
</script>
<style scoped>.check-issues{max-height:420px;overflow:auto}.check-drafts{display:inline-flex;align-items:center;gap:8px}.check-drafts input{display:inline-block;width:auto;margin:0}</style>
